css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .serie-cajas{display: flex; gap: 8px; flex-wrap: wrap; font-size: 17px; font-weight: 700; align-items: center;}
.mz .serie-cajas .caja-num{width: 60px; height: 44px; border: 1.5px solid var(--bosque); border-radius: 6px; display: flex; align-items: center; justify-content: center;}
.mz .serie-cajas .caja-num.vacia{background: #fff;}
.mz .serie-label{font-size: 13px; font-weight: 600; font-family: sans-serif; margin-bottom: 4px;}
.mz .serie-block{margin-bottom: 12px;}
